  ('selector', 'người tuyển chọn; bộ chọn, núm chọn', 'The national team selectors will announce the final squad next week.', 'Ban tuyển chọn đội tuyển quốc gia sẽ công bố danh sách cuối cùng vào tuần tới.', '/sɪˈlektər/', 'n'),
  ('suggestive', 'gợi ý, gợi nhớ; khiếm nhã, gợi dục', 'The soft music and candles were suggestive of a romantic evening.', 'Tiếng nhạc nhẹ và những ngọn nến gợi lên một buổi tối lãng mạn.', '/səɡˈdʒestɪv/', 'adj')
) AS v(word, meaning, example, example_vi, ipa, pos)
WHERE NOT EXISTS (
  SELECT 1 FROM vocab_card c
  WHERE c.deck_id = '22222222-2222-2222-2222-222222222204' AND lower(c.word) = lower(v.word)
);

UPDATE vocab_deck
SET card_count = (SELECT count(*) FROM vocab_card WHERE deck_id = '22222222-2222-2222-2222-222222222204')
WHERE id = '22222222-2222-2222-2222-222222222204';

COMMIT;
